import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import "./AdminB.css";

export default function AdminB() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const navigate = useNavigate();

  const handleLogin = (e) => {
    e.preventDefault();

    if (!username.trim() || !password.trim()) {
      setError("Por favor, completa todos los campos.");
      return;
    }

    setError("");

    const lowerUsername = username.toLowerCase();

    if (lowerUsername === "super") {
      navigate("/admin/adminS");
    } else if (lowerUsername.includes("ubicacion")) {
      navigate("/admin/adminU");
    } else if (lowerUsername.includes("proceso")) {
      navigate("/admin/adminP");
    } else {
      setError("Usuario no reconocido. Verifica tus credenciales.");
    }
  };

  return (
    <div className="admin-container">
      <header className="admin-header">
        <div className="header-content">
          <h1 className="header-title">TalkinPon</h1>
          <div className="header-center-text">
            <span>Inicio de sesión.</span>
          </div>
          <Link to="/">
            <img
              src="/university-logo-circular.jpg"
              alt="Logo"
              className="header-logo"
            />
          </Link>
        </div>
      </header>

      <main className="login-main">
        <div className="login-card">
          <h2 className="login-title">Bienvenido Administrador</h2>
          <form onSubmit={handleLogin} className="login-form">
            <div className="form-group">
              <label htmlFor="username">Usuario:</label>
              <input
                type="text"
                id="username"
                value={username}
                onChange={(e) => {
                  setUsername(e.target.value);
                  setError("");
                }}
                placeholder="Ingresa tu usuario..."
                required
              />
            </div>

            <div className="form-group">
              <label htmlFor="password">Contraseña:</label>
              <input
                type="password"
                id="password"
                value={password}
                onChange={(e) => {
                  setPassword(e.target.value);
                  setError("");
                }}
                placeholder="Ingresa tu contraseña..."
                required
              />
            </div>

            {error && <div className="error-message">{error}</div>}

            <button type="submit" className="login-button">
              Iniciar sesión
            </button>
          </form>
        </div>
      </main>
    </div>
  );
}
